import * as s from "../core/validation/index.js";
import type { JsonValue, Schema } from "../core/validation/schema.js";

export type TokenUsage = {
  /**
   * Non-cached input tokens. Matches Anthropic's `input_tokens` semantic (does not include cached
   * or cache-creation tokens).
   */
  inputTokens?: number;
  /** Output tokens generated by the model. */
  outputTokens?: number;
  /** Input tokens served from cache (cache hit). */
  cacheReadInputTokens?: number;
  /** Input tokens written to cache on this request (Anthropic prompt caching). */
  cacheCreationInputTokens?: number;
  /** Reasoning tokens emitted by reasoning models (o1/o3, Claude extended thinking). */
  reasoningOutputTokens?: number;
  /** Properties the service sent or accepts beyond those declared. */
  additionalProperties?: Record<string, JsonValue>;
};

export const tokenUsageSchema: Schema<TokenUsage> = s.object<TokenUsage>(
  {
    inputTokens: s.optional(s.int()),
    outputTokens: s.optional(s.int()),
    cacheReadInputTokens: s.optional(s.int()),
    cacheCreationInputTokens: s.optional(s.int()),
    reasoningOutputTokens: s.optional(s.int()),
  },
  { additionalProperties: s.json() },
);
